import { TestBed } from '@angular/core/testing';
import { provideRouter } from '@angular/router';
import { Watchlist } from '../app/watchlist/watchlist';
import { WatchlistStore } from '../app/watchlist-store';
import { routes } from '../app/app.routes';

describe('watchlist', () => {
  beforeEach(() => {
    localStorage.clear();
  });

  it('lists unwatched movies before watched movies', () => {
    TestBed.configureTestingModule({
      imports: [Watchlist],
      providers: [provideRouter(routes), WatchlistStore],
    });

    const store = TestBed.inject(WatchlistStore);
    const fixture = TestBed.createComponent(Watchlist);
    const component = fixture.componentInstance;

    store.add({ id: 101, title: 'Watched One', release_date: '2001-01-01', poster_path: null, overview: 'a' });
    store.add({ id: 102, title: 'Unwatched Two', release_date: '2002-02-02', poster_path: null, overview: 'b' });
    store.add({ id: 103, title: 'Watched Three', release_date: '2003-03-03', poster_path: null, overview: 'c' });
    store.add({ id: 104, title: 'Unwatched Four', release_date: '2004-04-04', poster_path: null, overview: 'd' });
    store.toggleWatched(101);
    store.toggleWatched(103);

    const rendered = component.movies();
    expect(rendered.map((m) => m.watched)).toEqual([false, false, true, true]);
    expect(rendered.filter((m) => !m.watched).map((m) => m.id)).toEqual([102, 104]);
    expect(rendered.filter((m) => m.watched).map((m) => m.id)).toEqual([101, 103]);

    fixture.detectChanges();
    const text = fixture.nativeElement.textContent as string;
    const firstUnwatched = text.indexOf('Unwatched Two');
    const firstWatched = text.indexOf('Watched One');
    expect(firstUnwatched).toBeGreaterThanOrEqual(0);
    expect(firstWatched).toBeGreaterThanOrEqual(0);
    expect(firstUnwatched).toBeLessThan(firstWatched);
  });
});
